def calculate_a_n(N):
    a = {1: 1, 2: 1}

    for n in range(3, N + 1):
        # a_n = a_{a_{n-1}} + a_{n - a_{n-1}}
        a_n_minus_1 = a[n-1]

        term1 = a[a_n_minus_1]
        term2 = a[n - a_n_minus_1]

        a[n] = term1 + term2

    return a

# Calculate up to N=16
a_values = calculate_a_n(16)

print("--- First 16 terms ---")
for n in range(1, 17):
    print(f"a_{n} = {a_values[n]}")

print("\n--- Powers of 2 ---")
k_values = [1, 2, 3, 4]
results = {}
for k in k_values:
    n = 2**k
    results[k] = a_values[n]
    print(f"a_{n} (k={k}) = {results[k]}")
